namespace MassiveArmy.EditorTools {
    public static class GameplayFeatureValidation {
        [Serializable]sealed class Report {public string status="PASS",error="",aiResearch="";public int checks;public bool playing,worldReady;}
        [Serializable]sealed class PrecisionReport {public string status="PASS",error="";public int samples;public double maxHeightError,maxDecalError;}
        [MenuItem("Synthetic Front/Validation/Check GPU crater and decal precision")]
        public static void RunPrecision(){
            var report=new PrecisionReport();ComputeShader shader=null;PlanetDefinition definition=null;PlanetTerrainEdits edits=null;
            try{
                shader=UnityEngine.Object.Instantiate(Resources.Load<ComputeShader>("MassiveArmy/PlanetTerrainValidation"));int kernel=shader.FindKernel("EditPrecision");
                foreach(float radius in new[]{60000f,6000000f,60000000f})foreach(bool multi in new[]{false,true}){
                    definition=ScriptableObject.CreateInstance<PlanetDefinition>();definition.radius=radius;definition.terrainHeight=0;definition.stampTerrain=false;definition.experimentalGpuDoublePrecision=true;definition.gpuDoubleMinimumRadius=0;edits=new PlanetTerrainEdits(definition);edits.AddCrater(new Vector3(.34f,.61f,.716f).normalized,80);
                    if(multi)edits.AddCrater(Vector3.left,100);
                    edits.Bind(shader);shader.EnableKeyword("PLANET_GPU_DOUBLE");
                    var values=(Vector4[])typeof(PlanetTerrainEdits).GetField("craters",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(edits);Vector3 stored=values[0];var centre=new Double3(stored);centre*=1/centre.Magnitude;var right=Double3.Cross(centre,new Double3(0,1,0));right*=1/right.Magnitude;
                    var observer=centre*radius;var high=observer.Float;shader.SetVector("_PlanetObserverHigh",high);shader.SetVector("_PlanetObserverLow",(observer-new Double3(high)).Float);shader.SetVector("_PrecisionStamp",stored);shader.SetFloat("_PlanetRadius",radius);shader.SetFloat("_PlanetHeight",0);
                    var inputs=new Vector4[16];var lows=new Vector4[16];var expected=new Double3[16];var heights=new double[16];
                    for(int i=0;i<inputs.Length;i++){var direction=centre+right*((10+i*.05)/radius);direction*=1/direction.Magnitude;Vector3 dh=direction.Float;inputs[i]=dh;lows[i]=(direction-new Double3(dh)).Float;double q=(direction-centre).Magnitude*radius/80;double height=-12.8*(1-q*q)*(1-q*q);heights[i]=height;if(Math.Abs(edits.Height(direction)-height)>.001)throw new InvalidOperationException("CPU crater contact does not match the double reference");expected[i]=direction*(radius+height)-observer;}
                    using(var directions=new GraphicsBuffer(GraphicsBuffer.Target.Structured,16,16))using(var low=new GraphicsBuffer(GraphicsBuffer.Target.Structured,16,16))using(var output=new GraphicsBuffer(GraphicsBuffer.Target.Structured,16,16)){
                        directions.SetData(inputs);low.SetData(lows);shader.SetBuffer(kernel,"_Directions",directions);shader.SetBuffer(kernel,"_DirectionLow",low);shader.SetBuffer(kernel,"_Samples",output);shader.SetInt("_SampleCount",16);shader.Dispatch(kernel,1,1,1);var samples=new Vector4[16];output.GetData(samples);
                        for(int i=0;i<samples.Length;i++){report.samples++;double heightError=Math.Abs(samples[i].x-heights[i]);var local=new Double3(samples[i].y,samples[i].z,samples[i].w);double decalError=(local-expected[i]).Magnitude;report.maxHeightError=Math.Max(report.maxHeightError,heightError);report.maxDecalError=Math.Max(report.maxDecalError,decalError);if(double.IsNaN(heightError)||double.IsNaN(decalError)||heightError>.001||decalError>.001)throw new InvalidOperationException("GPU precision error at radius "+radius+", multi="+multi+", sample="+i+": height="+heightError+", decal="+decalError);}
                    }
                    edits.Dispose();edits=null;UnityEngine.Object.DestroyImmediate(definition);definition=null;
                }
            }catch(Exception error){report.status="FAIL";report.error=error.ToString();Debug.LogException(error);}finally{edits?.Dispose();if(definition!=null)UnityEngine.Object.DestroyImmediate(definition);if(shader!=null)UnityEngine.Object.DestroyImmediate(shader);Directory.CreateDirectory("TestResults/Gameplay");File.WriteAllText("TestResults/Gameplay/crater-decal-precision.json",JsonUtility.ToJson(report,true));}
        }
        [Serializable]sealed class MotionReport {public string status="PASS",error="";public System.Collections.Generic.List<string> results=new System.Collections.Generic.List<string>();}
        public static void RunVehicleMotion(){
            var report=new MotionReport();try{foreach(string id in new[]{"SF-LUV1","SF-QB1","SF-TK1"})foreach(float radius in new[]{60000f,6000000f,60000000f}){
                var definition=ScriptableObject.CreateInstance<PlanetDefinition>();GameObject fixture=null;VehicleRigPool pool=null;VehicleController controller=null;
                try{definition.radius=radius;definition.terrainHeight=1000;definition.stampTerrain=false;definition.gravitationalParameter=9.81*(double)radius*radius;
                    var surface=new PlanetSurface(definition);var vehicle=Resources.Load<VehicleDefinition>("MassiveArmy/Vehicles/"+id);var up=new Vector3(.34f,.61f,.716f).normalized;var point=surface.GetSurfacePositionPrecise(up,.025);
                    fixture=new GameObject("Temporary detailed vehicle motion check");var world=fixture.AddComponent<PlanetDevelopment>();world.definition=definition;var camera=new GameObject("Validation camera").AddComponent<Camera>();camera.transform.SetParent(fixture.transform,false);var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;typeof(PlanetDevelopment).GetField("origin",flags).SetValue(world,new FloatingOrigin(definition.position.Add(point)));typeof(PlanetDevelopment).GetField("view",flags).SetValue(world,camera);
                    pool=new VehicleRigPool(fixture.transform);var contact=new VehicleTerrainContact(surface,p=>(p-point).Float,p=>point+new Double3(p));controller=new VehicleController(world,contact,pool,vehicle,0,new SpacePose{position=point,rotation=Quaternion.LookRotation(Vector3.ProjectOnPlane(Vector3.forward,up).normalized,up)});controller.Seats.TryEnterPlayer(0);controller.SetDetail(true);
                    for(int i=0;i<600;i++){controller.Rebase();Physics.SyncTransforms();controller.Tick(1f/60,new VehicleInput{movement=Vector2.up},null);}
                    double travelled=(controller.Motor.Pose.position-point).Magnitude;report.results.Add(id+" radius "+radius+": "+travelled+" m; speed "+controller.Motor.ForwardSpeed+"; state "+controller.Motor.State+"; detailed driver seat "+controller.Controlled);if(travelled<20)report.status="FAIL";
                }finally{controller?.Dispose();pool?.Dispose();if(fixture!=null)UnityEngine.Object.DestroyImmediate(fixture);UnityEngine.Object.DestroyImmediate(definition);}
            }}catch(Exception error){report.status="FAIL";report.error=error.ToString();}Directory.CreateDirectory("TestResults/Gameplay");File.WriteAllText("TestResults/Gameplay/vehicle-motion.json",JsonUtility.ToJson(report,true));
        }
        [MenuItem("Synthetic Front/Terrain/Texture and distance settings")]
        public static void EditTerrainSettings(){Selection.activeObject=Resources.Load<MassiveArmy.TerrainSurfaceLibrary>("MassiveArmy/TerrainArt/SurfaceLibrary");EditorGUIUtility.PingObject(Selection.activeObject);}
        public static void RunPubValidation(){var report=new MotionReport();GameObject root=null;try{var catalog=MassiveArmy.RtsModelArt.Load();var pub=catalog.Find("civil_pub")?.modular;if(pub==null)throw new InvalidOperationException("Pub modular layout is not selected");void Check(bool condition,string text){if(!condition)throw new InvalidOperationException(text);report.results.Add(text);}Check(pub.rooms.Length>=10&&pub.doors.Length==5,"Separate public rooms, gallery, apartments and five interactive doors");Check(pub.rooms.Count(r=>r.name.StartsWith("Apartment"))==2,"Two rental apartments");Check(pub.proxy.triangles.Length==36,"Twelve-triangle far pub LOD");Check(pub.rooms[0].bounds.Contains(new Vector3(-6,1,-2.7f)),"Bartender station lies in the public bar");root=new GameObject("Temporary pub collision check");root.layer=30;var collider=root.AddComponent<MeshCollider>();collider.sharedMesh=pub.collision;Physics.SyncTransforms();Check(Physics.Raycast(new Vector3(0,6,0),Vector3.down,out var atrium,8,1<<30)&&Math.Abs(atrium.point.y)<.02,"Gallery has an open void over the bar");Check(Physics.Raycast(new Vector3(-10,4.4f,0),Vector3.down,out var gallery,2,1<<30)&&Math.Abs(gallery.point.y-3.6)<.02,"Upper gallery has a collidable floor");Check(Physics.Raycast(new Vector3(0,2.4f,-8),Vector3.down,out var stairs,3,1<<30)&&Math.Abs(stairs.point.y-1.63636)<.04,"Staircase has a smooth walkable collision ramp");Check(!Physics.Raycast(new Vector3(0,1.2f,14),Vector3.back,3,1<<30),"Exterior doorway is a real aperture");Check(catalog.Find(CivilisationRuntime.FuneralDirectors)?.modular!=null,"Funeral directors use modular art");}catch(Exception error){report.status="FAIL";report.error=error.ToString();}finally{if(root!=null)UnityEngine.Object.DestroyImmediate(root);Directory.CreateDirectory("TestResults/Gameplay");File.WriteAllText("TestResults/Gameplay/pub-validation.json",JsonUtility.ToJson(report,true));}}
        struct FixtureNode {public Vector4 position;public int a,b,c,d;}
        struct FixtureJob {public Vector4 start,goal;public uint version,startNode,goalNode,flags;public Vector4 parameters;}
        struct FixturePose {public Vector4 position,right,up,forward,properties;}
        struct FixtureSummary {public uint version,arrived;public float distance;public uint status;}
        struct FixtureCitizen {public uint health,damage,generation,flags;public float cooldown;public uint patrol,lastHit,pad;public Vector4 body;}
        public static void RunCivicGpu(){var report=new MotionReport();var buffers=new System.Collections.Generic.List<GraphicsBuffer>();ComputeShader roads=null,people=null;
            GraphicsBuffer B(int count,int stride){var buffer=new GraphicsBuffer(GraphicsBuffer.Target.Structured,count,stride);buffers.Add(buffer);return buffer;}
            void Check(bool condition,string text){if(!condition)throw new InvalidOperationException(text);report.results.Add(text);}
            try{roads=UnityEngine.Object.Instantiate(Resources.Load<ComputeShader>("MassiveArmy/SettlementRoad"));int kernel=roads.FindKernel("Navigate");var nodes=B(1,32);nodes.SetData(new[]{new FixtureNode{position=new Vector4(0,60000,0,0),a=-1,b=-1,c=-1,d=-1}});var jobs=B(1,64);var work=B(1,48);var seen=B(1,4);var parents=B(1,4);var queue=B(1,4);var distance=B(1,4);var summary=B(1,16);var poses=B(1,80);
                roads.SetBuffer(kernel,"_RoadNodes",nodes);roads.SetBuffer(kernel,"_RailNodes",nodes);roads.SetBuffer(kernel,"_RoadJobs",jobs);roads.SetBuffer(kernel,"_RoadWork",work);roads.SetBuffer(kernel,"_RoadSeen",seen);roads.SetBuffer(kernel,"_RoadParents",parents);roads.SetBuffer(kernel,"_RoadQueue",queue);roads.SetBuffer(kernel,"_RoadDistances",distance);roads.SetBuffer(kernel,"_RoadSummary",summary);roads.SetBuffer(kernel,"_CargoPoses",poses);roads.SetInt("_RoadCount",1);roads.SetInt("_RailCount",0);roads.SetInt("_RoadStride",1);roads.SetInt("_CargoCount",1);roads.SetInt("_RoadRevision",1);roads.SetFloat("_CargoDelta",.25f);roads.SetFloat("_RoadLaneOffset",3);roads.SetInt("_RaiderCampCount",0);
                int clear=roads.FindKernel("ClearSearch");roads.SetBuffer(clear,"_RoadWork",work);roads.SetBuffer(clear,"_RoadSeen",seen);roads.SetInt("_SearchSlots",1);roads.SetInt("_StorageWidth",128);roads.Dispatch(clear,1,1,1);
                var job=new FixtureJob{start=new Vector4(0,60000,0,1),goal=new Vector4(11,60000.7f,8,0),version=1,flags=64,parameters=new Vector4(4,0,60000,43)};jobs.SetData(new[]{job});roads.Dispatch(kernel,1,1,1);var result=new FixtureSummary[1];summary.GetData(result);Check(result[0].arrived==0,"Hearse does not report arrival before entering its parking bay");for(int i=0;i<40;i++)roads.Dispatch(kernel,1,1,1);summary.GetData(result);var parked=new FixturePose[1];poses.GetData(parked);Check(result[0].arrived==1&&Math.Abs(parked[0].position.x-11)<.01&&Math.Abs(parked[0].position.z-8)<.01,"GPU road vehicle completes the final approach into the marked parking position");job.version=2;job.flags=68;jobs.SetData(new[]{job});roads.Dispatch(kernel,1,1,1);poses.GetData(parked);Check(Math.Abs(parked[0].position.y-60000.05)<.02,"Idle hearse stays parked at ground clearance");
                people=UnityEngine.Object.Instantiate(Resources.Load<ComputeShader>("MassiveArmy/SettlementCitizens"));int pick=people.FindKernel("PickPerson");var citizens=B(1,48);var personPoses=B(1,80);var output=B(1,4);var person=new FixtureCitizen{health=100,generation=1,flags=1,body=new Vector4(11,60000000,8,0)};var pose=new FixturePose{position=person.body,up=new Vector4(0,1,0,0),right=new Vector4(1,0,0,.018f),forward=new Vector4(0,0,1,0),properties=new Vector4(0,0,0,1)};personPoses.SetData(new[]{pose});people.SetBuffer(pick,"_CivicStates",citizens);people.SetBuffer(pick,"_CargoPoses",personPoses);people.SetBuffer(pick,"_NearbyPerson",output);people.SetInt("_WalkerCount",1);people.SetVector("_PersonRayHigh",new Vector3(11,60000020,8));people.SetVector("_PersonRayLow",new Vector3(.018f,0,0));people.SetVector("_PersonRayDirection",Vector3.down);
                foreach(bool corpse in new[]{false,true}){person.health=corpse?0u:100u;person.flags=corpse?512u:1u;citizens.SetData(new[]{person});output.SetData(new[]{uint.MaxValue});people.Dispatch(pick,1,1,1);var selection=new uint[1];output.GetData(selection);Check(selection[0]!=uint.MaxValue&&(selection[0]&65535)==0,corpse?"Corpse ray hover resolves the recorded civilian":"Living civilian ray click resolves identity with split camera coordinates at 1000x");}
            }catch(Exception error){report.status="FAIL";report.error=error.ToString();}finally{foreach(var buffer in buffers)buffer.Dispose();if(roads!=null)UnityEngine.Object.DestroyImmediate(roads);if(people!=null)UnityEngine.Object.DestroyImmediate(people);Directory.CreateDirectory("TestResults/Gameplay");File.WriteAllText("TestResults/Gameplay/civic-gpu-validation.json",JsonUtility.ToJson(report,true));}
        }
        [MenuItem("Synthetic Front/Validation/Check personal gameplay and research assets")]
        public static void Run(){var report=new Report();void Check(bool condition,string message){if(!condition)throw new InvalidOperationException(message);report.checks++;}
            try{
                var catalog=RtsCatalog.Load();var civilisation=CivilisationCatalogue.Load();civilisation.Extend(catalog);var positions=TechnologyGraphLayout.Arrange(catalog.technologies);
                Check(positions.Count==catalog.technologies.Length,"Every technology has one node");var rectangles=positions.Values.ToArray();for(int i=0;i<rectangles.Length;i++)for(int j=i+1;j<rectangles.Length;j++)if(rectangles[i].Overlaps(rectangles[j]))throw new InvalidOperationException("Research graph nodes overlap");Check(true,"No overlapping research nodes");
                foreach(var tech in catalog.technologies)foreach(string parent in tech.prerequisites)if(positions[parent].xMax>=positions[tech.id].xMin)throw new InvalidOperationException("Research graph dependency runs backwards");Check(true,"Dependencies advance through columns");
                var items=PersonalItemCatalogue.Load();Check(items.items.Select(x=>x.id).Distinct().Count()==items.items.Length,"Unique personal item identifiers");Check(items.items.Count(x=>x.kind==PersonalItemKind.Firearm)>=10,"Multiple firearm types");Check(items.Find("katana")?.kind==PersonalItemKind.Melee&&items.Find("crossbow")?.kind==PersonalItemKind.Bow,"Melee and bow items registered");
                var quad=Resources.Load<VehicleDefinition>("MassiveArmy/Vehicles/SF-QB1");Check(quad!=null,"Quad asset generated");Check(quad.seats.Length==1&&quad.wheels.Length==4&&quad.ValidateDefinition().Length==0,"Valid one-seat four-wheel quad");Check(quad.prefab.GetComponent<LODGroup>().GetLODs().Length==3,"Quad has detailed/proxy/bounds LODs");
                report.playing=EditorApplication.isPlaying;var world=UnityEngine.Object.FindAnyObjectByType<PlanetDevelopment>();report.worldReady=world?.Ready==true;
                if(report.worldReady&&world.Base!=null)report.aiResearch=string.Join("; ",world.Base.Factions.Select(f=>"Faction "+f.team+": completed "+f.technologies.Count+", researching "+string.Join(",",f.researching)));
            }catch(Exception error){report.status="FAIL";report.error=error.ToString();Debug.LogException(error);}
            Directory.CreateDirectory("TestResults/Gameplay");File.WriteAllText("TestResults/Gameplay/editor-validation.json",JsonUtility.ToJson(report,true));Debug.Log("Gameplay feature checks: "+report.status+" ("+report.checks+")");
        }
